const { AbstractExport } = require('../abstract-export');
const { ajv } = require('../ajv');
require('./expression');
require('./namespace');

const schema = {
  type: 'object',
  properties: {
    version: {type: 'string', pattern: '^L[123]V[12345]$'},
  }
};

class SBMLExport extends AbstractExport {
  constructor(q = {}, isCore = false){
    super(q, isCore);

    // check arguments here
    let { logger } = this._builder;
    let valid = SBMLExport.isValid(q, logger);
    if (!valid) { this.errored = true; return; }

    if (typeof q.version !== 'undefined') {
      this.version = q.version;
    } else {
      this.version = 'L2V4';
    } 
  }
  get className(){
    return 'SBMLExport';
  }
  get defaultFilepath() {
    return 'sbml';
  }
  get format(){
    return 'sbml';
  }
  static get validate(){
    return ajv.compile(schema);
  }
  makeText(){
    //let { logger } = this._builder;
    
    // filter namespaces if set
    let selectedNamespaces = this.selectedNamespaces();

    let results = selectedNamespaces.map(([spaceName, ns]) => {
      let image = ns.getSBMLImage();
      var content = this.getSBMLCode(image);
      
      return {
        content: content,
        pathSuffix: `/${spaceName}.xml`,
        type: 'text'
      };
    });

    return results;
  }

  getSBMLCode(image = {}){
    switch (this.version) {
    case 'L2V3':
      return this.renderTemplate('sbmlL2V3.xml.njk', image);
      break;
    case 'L2V4':
      return this.renderTemplate('sbmlL2V4.xml.njk', image);
      break;
    case 'L2V5':
      return this.renderTemplate('sbmlL2V5.xml.njk', image);
      break;
    case 'L3V1':
      return this.renderTemplate('sbmlL3V1.xml.njk', image);
      break;
    case 'L3V2':
      return this.renderTemplate('sbmlL3V2.xml.njk', image);
      break;
    default:
      this._builder.logger.error(`SBML of version "${this.version}" is not supported.`);
      return '';
    }
    
  }
}

module.exports = SBMLExport;
